"""API cost tracker — 记录所有 LLM API 调用的 token 使用量和费用估算。"""

import logging
from dataclasses import dataclass, field
from threading import Lock

logger = logging.getLogger(__name__)

DEFAULT_PRICING = {
    "deepseek-chat": {"input": 0.14, "output": 0.28},
    "deepseek-reasoner": {"input": 0.55, "output": 2.19},
    "deepseek/deepseek-v3.2": {"input": 0.27, "output": 1.10},
    "deepseek/deepseek-v4-pro": {"input": 0.80, "output": 3.20},
}

# Local vLLM: no per-token API cost, tracked as GPU-hours instead.
# RTX 5090 ~$1.50/h/card. TP=2 = $3.00/h total.
LOCAL_GPU_COST_PER_HOUR = 3.0


@dataclass
class CostTracker:
    """Thread-safe API cost tracker."""

    pricing: dict = field(default_factory=lambda: dict(DEFAULT_PRICING))
    _records: list = field(default_factory=list, repr=False)
    _lock: Lock = field(default_factory=Lock, repr=False)
    _total_input_tokens: int = 0
    _total_output_tokens: int = 0

    def record(self, model: str, prompt_tokens: int, completion_tokens: int, module: str = ""):
        with self._lock:
            self._total_input_tokens += prompt_tokens
            self._total_output_tokens += completion_tokens
            self._records.append({
                "model": model,
                "prompt_tokens": prompt_tokens,
                "completion_tokens": completion_tokens,
                "total_tokens": prompt_tokens + completion_tokens,
                "module": module,
            })
        logger.debug("API call [%s/%s]: %d+%d tokens", module, model, prompt_tokens, completion_tokens)

    def summary(self) -> dict:
        with self._lock:
            by_module: dict = {}
            by_model: dict = {}
            for r in self._records:
                mod = r["module"] or "unknown"
                if mod not in by_module:
                    by_module[mod] = {"calls": 0, "input_tokens": 0, "output_tokens": 0}
                by_module[mod]["calls"] += 1
                by_module[mod]["input_tokens"] += r["prompt_tokens"]
                by_module[mod]["output_tokens"] += r["completion_tokens"]

                mdl = r["model"]
                if mdl not in by_model:
                    by_model[mdl] = {"calls": 0, "input_tokens": 0, "output_tokens": 0}
                by_model[mdl]["calls"] += 1
                by_model[mdl]["input_tokens"] += r["prompt_tokens"]
                by_model[mdl]["output_tokens"] += r["completion_tokens"]

            total_cost = 0.0
            model_costs: dict = {}
            for mdl, counts in by_model.items():
                prices = self.pricing.get(mdl, {"input": 0.0, "output": 0.0})
                cost = (counts["input_tokens"] / 1_000_000 * prices["input"]
                        + counts["output_tokens"] / 1_000_000 * prices["output"])
                model_costs[mdl] = round(cost, 6)
                total_cost += cost

            return {
                "total_calls": len(self._records),
                "total_input_tokens": self._total_input_tokens,
                "total_output_tokens": self._total_output_tokens,
                "total_tokens": self._total_input_tokens + self._total_output_tokens,
                "estimated_cost_usd": round(total_cost, 6),
                "by_module": by_module,
                "by_model": {
                    mdl: {**counts, "estimated_cost_usd": model_costs.get(mdl, 0)}
                    for mdl, counts in by_model.items()
                },
            }


_global_tracker = CostTracker()


def get_tracker() -> CostTracker:
    return _global_tracker


def reset_tracker():
    global _global_tracker
    _global_tracker = CostTracker()

"""Z3-based internal consistency checker for single reasoning chains.

Builds Z3 contexts from vocabulary, parses FOL strings into Z3 expressions,
checks satisfiability of claim conjunctions, and computes greedy MCS when
inconsistencies are found.
"""

import logging
from typing import Optional

import z3

from ..types import AtomicClaim
from ..config import VerificationConfig

logger = logging.getLogger(__name__)


class Z3Checker:

    def __init__(self, config: VerificationConfig):
        self.config = config

    def build_z3_context(self, vocab: dict) -> dict:
        """Create Z3 symbols from a vocabulary dict.

        vocab format:
            {"predicates": {"Green": {"arity": 1}, "Likes": {"arity": 2}},
             "constants":  {"cat": {"sort": "entity"}, "dog": {"sort": "entity"}}}

        Returns dict mapping name -> z3 object (Functions and Consts).
        """
        ctx = {}

        for name, info in vocab.get("predicates", {}).items():
            arity = info["arity"]
            sorts = [z3.IntSort()] * arity + [z3.BoolSort()]
            ctx[name] = z3.Function(name, *sorts)

        for name, _info in vocab.get("constants", {}).items():
            ctx[name] = z3.Const(name, z3.IntSort())

        return ctx

    def parse_fol_to_z3(self, fol_str: str, z3_ctx: dict) -> Optional[z3.ExprRef]:
        """Parse a FOL string into a Z3 expression using the given context.

        The fol_str is expected to be a Z3 Python expression string like
        "ForAll([x], Implies(Green(x), Big(x)))".
        """
        namespace = {
            "ForAll": z3.ForAll,
            "Exists": z3.Exists,
            "Implies": z3.Implies,
            "And": z3.And,
            "Or": z3.Or,
            "Not": z3.Not,
            "Int": z3.Int,
            "IntSort": z3.IntSort,
            "BoolSort": z3.BoolSort,
            "Bool": z3.Bool,
            "Function": z3.Function,
            "Const": z3.Const,
            "x": z3.Int("x"),
            "y": z3.Int("y"),
            "z": z3.Int("z"),
            "w": z3.Int("w"),
        }
        namespace.update(z3_ctx)

        try:
            expr = eval(fol_str, {"__builtins__": {}}, namespace)
            if not isinstance(expr, z3.ExprRef):
                logger.warning("FOL eval did not produce z3.ExprRef: %s", fol_str)
                return None
            return expr
        except Exception as e:
            logger.warning("Failed to parse FOL '%s': %s", fol_str, e)
            return None

    def check_internal_consistency(
        self, claims: list[AtomicClaim], vocab: dict, total_claims: int = 0,
        premise_fols: list[str] | None = None,
    ) -> tuple[bool, float, int]:
        """Check whether formalized claims in a chain are internally consistent.

        Args:
            total_claims: total number of claims (including non-formalized).
                          When >0, used as denominator for IC score so that
                          chains with low formalization rates are penalized.
            premise_fols: formalized premise FOL strings (PCV). When provided,
                          premises are added as fixed constraints before chain claims.

        Returns:
            (is_sat, ic_score, mcs_size)
            - is_sat: True if the full conjunction is satisfiable
            - ic_score: coverage-adjusted consistency score
            - mcs_size: number of claims in the maximal consistent subset
        """
        z3_ctx = self.build_z3_context(vocab)
        formalized = [c for c in claims if c.z3_parseable and c.fol]

        if not formalized:
            return (True, 0.0, 0)

        exprs = []
        for claim in formalized:
            expr = self.parse_fol_to_z3(claim.fol, z3_ctx)
            if expr is not None:
                exprs.append(expr)

        if not exprs:
            return (True, 0.0, 0)

        denom = total_claims if total_claims > 0 else len(formalized)

        premise_exprs = []
        if premise_fols:
            for pfol in premise_fols:
                pexpr = self.parse_fol_to_z3(pfol, z3_ctx)
                if pexpr is not None:
                    premise_exprs.append(pexpr)

        solver = z3.Solver()
        solver.set("timeout", self.config.z3_timeout_ms)
        for pe in premise_exprs:
            solver.add(pe)
        solver.add(*exprs)

        result = solver.check()

        if result == z3.sat:
            logger.info("Chain internally consistent: %d claims all SAT", len(exprs))
            ic_score = len(formalized) / denom
            return (True, ic_score, len(formalized))

        if result == z3.unsat:
            logger.info("Chain inconsistent, computing greedy MCS")
            mcs, mcs_size = self.greedy_mcs(formalized, vocab, premise_fols=premise_fols)
            ic_score = mcs_size / denom
            return (False, ic_score, mcs_size)

        # z3.unknown (timeout) — treat as consistent with penalty
        logger.warning("Z3 returned unknown (timeout), treating as consistent")
        ic_score = len(formalized) / denom
        return (True, ic_score, len(formalized))

    def _check_sat_set(
        self, claims: list[AtomicClaim], z3_ctx: dict,
        premise_exprs: list[z3.ExprRef] | None = None,
    ) -> bool:
        """Check if a set of claims is satisfiable."""
        exprs = []
        for c in claims:
            if c.z3_parseable and c.fol:
                expr = self.parse_fol_to_z3(c.fol, z3_ctx)
                if expr is not None:
                    exprs.append(expr)
        if not exprs:
            return True
        solver = z3.Solver()
        solver.set("timeout", self.config.z3_timeout_ms)
        if premise_exprs:
            for pe in premise_exprs:
                solver.add(pe)
        solver.add(*exprs)
        return solver.check() == z3.sat

    def greedy_mcs(
        self, claims: list[AtomicClaim], vocab: dict,
        premise_fols: list[str] | None = None,
    ) -> tuple[list[AtomicClaim], int]:
        """Compute a greedy maximal consistent subset (VERGE-style).

        Iteratively tries removing each claim. If the removal makes the
        remaining set SAT, keep the removal and stop (single-conflict case).
        If no single removal suffices (multiple independent conflicts),
        force-remove the last claim and repeat.

        Premises (when provided) are fixed constraints — never removed during MCS.
        """
        z3_ctx = self.build_z3_context(vocab)

        premise_exprs = []
        if premise_fols:
            for pfol in premise_fols:
                pexpr = self.parse_fol_to_z3(pfol, z3_ctx)
                if pexpr is not None:
                    premise_exprs.append(pexpr)

        remaining = list(claims)

        while len(remaining) > 1:
            if self._check_sat_set(remaining, z3_ctx, premise_exprs=premise_exprs or None):
                break

            found_removal = False
            for i in range(len(remaining) - 1, -1, -1):
                candidate = remaining[i]
                test_set = remaining[:i] + remaining[i + 1:]

                if self._check_sat_set(test_set, z3_ctx, premise_exprs=premise_exprs or None):
                    remaining = test_set
                    found_removal = True
                    logger.debug(
                        "Removed claim (chain %d, idx %d) — now SAT with %d claims",
                        candidate.chain_id, candidate.claim_index, len(remaining),
                    )
                    break

            if not found_removal:
                removed = remaining.pop()
                logger.debug(
                    "Force-removed claim (chain %d, idx %d) — no single removal sufficed",
                    removed.chain_id, removed.claim_index,
                )

        return (remaining, len(remaining))

    def check_entailment(
        self, claims: list[AtomicClaim], vocab: dict,
        premise_fols: list[str], conclusion_fol: str,
    ) -> tuple[bool, str]:
        """Check if premises ∧ chain_claims ⊨ conclusion.

        Tests: premises ∧ claims ∧ ¬conclusion → UNSAT?
        If UNSAT, the reasoning entails the conclusion.

        Returns:
            (entails, status): entails=True if UNSAT, status in
            {"entails", "not_entails", "unknown", "parse_error"}
        """
        z3_ctx = self.build_z3_context(vocab)

        solver = z3.Solver()
        solver.set("timeout", self.config.z3_timeout_ms)

        for pfol in premise_fols:
            expr = self.parse_fol_to_z3(pfol, z3_ctx)
            if expr is not None:
                solver.add(expr)

        for c in claims:
            if c.z3_parseable and c.fol:
                expr = self.parse_fol_to_z3(c.fol, z3_ctx)
                if expr is not None:
                    solver.add(expr)

        concl_expr = self.parse_fol_to_z3(conclusion_fol, z3_ctx)
        if concl_expr is None:
            return (False, "parse_error")
        solver.add(z3.Not(concl_expr))

        result = solver.check()
        if result == z3.unsat:
            return (True, "entails")
        elif result == z3.sat:
            return (False, "not_entails")
        else:
            return (False, "unknown")

"""Vocabulary normalizer: extract shared predicate/constant vocabularies from problems.

Ensures all chains for a problem use the same predicate and constant names,
which is critical for cross-chain logical coherence (CCLC) — without shared
vocabulary, Z3 treats different symbol names as independent and the conjunction
becomes trivially satisfiable.

Input: Problem (premises + hypothesis)
Output: dict with "predicates" and "constants" mappings
"""

import logging
import json
import re

from openai import OpenAI

from ..types import Problem
from ..config import APIConfig
from ..cost_tracker import get_tracker

logger = logging.getLogger(__name__)

# Regex patterns for ProofWriter's stylized English
_ENTITY_PAT = re.compile(
    r"\b(?:The\s+)?([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)\b"
    r"(?=\s+(?:is|likes|chases|sees|visits|eats|needs|does))"
)
_UNARY_IS_PAT = re.compile(
    r"\b(?:[Tt]he\s+)?(\w+(?:\s+\w+)?)\s+is\s+(?:not\s+)?(\w+)\b"
)
_BINARY_VERB_PAT = re.compile(
    r"\b(?:[Tt]he\s+)?(\w+(?:\s+\w+)?)\s+(likes|chases|sees|visits|eats|needs|does\s+not\s+\w+|does\s+\w+)\s+(?:the\s+)?(\w+(?:\s+\w+)?)\b",
    re.IGNORECASE,
)

# Pronouns and function words that regex mistakenly captures as constants
_CONSTANT_STOPWORDS = {
    "something", "someone", "it", "they", "them", "he", "she",
    "everything", "nothing", "anything", "everyone", "no one",
    "this", "that", "these", "those", "who", "what", "which",
}


def _filter_constants(constants: dict) -> dict:
    """Remove pronouns, connective residue, and single-char noise from constants."""
    filtered = {}
    for name, info in constants.items():
        lower = name.lower().strip()
        if lower in _CONSTANT_STOPWORDS:
            continue
        if lower.startswith(("if_", "then_", "and_", "or_")):
            continue
        if any(lower.endswith(s) for s in ("_then", "_and", "_or", "_not", "_if")):
            continue
        if len(lower) <= 1:
            continue
        filtered[name] = info
    return filtered


def _normalize_predicate(name: str) -> str:
    """Strip third-person -s to get verb stem: Needs→Need, Chases→Chase."""
    if name.endswith("s") and not name.endswith("ss") and len(name) > 2:
        return name[:-1]
    return name


def _predicate_description(stem: str, arity: int) -> str:
    """Generate readable description from predicate stem."""
    lower = stem.lower()
    if arity == 1:
        return f"is {lower}"
    return f"{lower}s (relation)"


def _normalize_predicates(predicates: dict) -> dict:
    """Merge inflected variants (Need/Needs) into a single canonical predicate."""
    merged: dict[str, dict] = {}
    for name, info in predicates.items():
        canonical = _normalize_predicate(name) if info["arity"] == 2 else name
        if canonical not in merged:
            merged[canonical] = {
                "arity": info["arity"],
                "description": _predicate_description(canonical, info["arity"]),
            }
    return merged

_LLM_VOCAB_PROMPT = """\
You are a logic formalization assistant. Given a set of natural language premises and a hypothesis, \
extract a shared vocabulary of predicates and constants for first-order logic formalization.

**Rules:**
- Predicates are properties (unary) or relations (binary). Use CamelCase names.
- Constants are named entities. Use lowercase snake_case.
- Every predicate and constant that appears in the premises or hypothesis must be included.
- Do NOT invent predicates/constants not grounded in the text.

**Output format (strict JSON, no extra text):**
```json
{
  "predicates": {
    "PredicateName": {"arity": 1, "description": "short description"},
    ...
  },
  "constants": {
    "entity_name": {"sort": "entity", "description": "short description"},
    ...
  }
}
```

Premises:
{premises}

Hypothesis:
{hypothesis}

Extract the vocabulary now. Output only the JSON object."""


class VocabNormalizer:
    def __init__(self, api_config: APIConfig | None = None):
        self._api = api_config
        if api_config:
            self._client = OpenAI(
                base_url=api_config.formalization_base_url,
                api_key=[REDACTED],
                timeout=api_config.timeout,
            )

    def extract_vocab(self, problem: Problem) -> dict:
        """Auto-select extraction mode: regex for ProofWriter, LLM for others."""
        if problem.dataset == "proofwriter":
            vocab = self.normalize_vocab_regex(problem)
            if vocab["predicates"] or vocab["constants"]:
                logger.info(
                    "Regex extraction for %s: %d predicates, %d constants",
                    problem.id,
                    len(vocab["predicates"]),
                    len(vocab["constants"]),
                )
                return vocab
            logger.warning(
                "Regex extraction empty for %s, falling back to LLM", problem.id
            )
        return self.normalize_vocab_llm(problem)

    # ------------------------------------------------------------------
    # Regex-based extraction (ProofWriter)
    # ------------------------------------------------------------------

    def normalize_vocab_regex(self, problem: Problem) -> dict:
        predicates: dict[str, dict] = {}
        constants: dict[str, dict] = {}

        all_text = problem.premises + [problem.hypothesis]

        for sent in all_text:
            self._extract_unary(sent, predicates, constants)
            self._extract_binary(sent, predicates, constants)

        # second pass: pick up entity names that only appeared as objects
        for sent in all_text:
            for m in _ENTITY_PAT.finditer(sent):
                name = m.group(1).lower().replace(" ", "_")
                if name not in constants and name not in {
                    p.lower() for p in predicates
                }:
                    constants[name] = {"sort": "entity", "description": name}

        constants = _filter_constants(constants)
        predicates = _normalize_predicates(predicates)
        return {"predicates": predicates, "constants": constants}

    @staticmethod
    def _extract_unary(
        sent: str, predicates: dict, constants: dict
    ) -> None:
        for m in _UNARY_IS_PAT.finditer(sent):
            subj = m.group(1).lower().replace(" ", "_")
            prop = m.group(2).capitalize()
            if prop.lower() in ("not", "a", "an", "the"):
                continue
            predicates.setdefault(
                prop, {"arity": 1, "description": f"is {prop.lower()}"}
            )
            constants.setdefault(
                subj, {"sort": "entity", "description": subj}
            )

    @staticmethod
    def _extract_binary(
        sent: str, predicates: dict, constants: dict
    ) -> None:
        for m in _BINARY_VERB_PAT.finditer(sent):
            subj = m.group(1).lower().replace(" ", "_")
            verb = m.group(2).strip().split()[0].capitalize()
            obj = m.group(3).lower().replace(" ", "_")
            pred_name = verb
            # "does not chase" → "Chase" (negation handled at FOL level)
            if verb.lower() == "does":
                parts = m.group(2).strip().split()
                if len(parts) >= 2:
                    pred_name = parts[-1].capitalize()
            predicates.setdefault(
                pred_name, {"arity": 2, "description": f"{pred_name.lower()} (relation)"}
            )
            constants.setdefault(
                subj, {"sort": "entity", "description": subj}
            )
            constants.setdefault(
                obj, {"sort": "entity", "description": obj}
            )

    # ------------------------------------------------------------------
    # LLM-based extraction (FOLIO and fallback)
    # ------------------------------------------------------------------

    def normalize_vocab_llm(self, problem: Problem) -> dict:
        if not self._api:
            raise ValueError("LLM vocab extraction requires an APIConfig")

        premises_text = "\n".join(
            f"{i+1}. {p}" for i, p in enumerate(problem.premises)
        )
        prompt = _LLM_VOCAB_PROMPT.format(
            premises=premises_text, hypothesis=problem.hypothesis
        )

        last_error = None
        for attempt in range(self._api.max_retries):
            try:
                resp = self._client.chat.completions.create(
                    model=self._api.formalization_model,
                    messages=[{"role": "user", "content": prompt}],
                    temperature=0.0,
                    max_tokens=1024,
                )
                if hasattr(resp, 'usage') and resp.usage:
                    get_tracker().record(
                        model=self._api.formalization_model,
                        prompt_tokens=resp.usage.prompt_tokens or 0,
                        completion_tokens=resp.usage.completion_tokens or 0,
                        module="vocab_normalizer",
                    )
                text = resp.choices[0].message.content.strip()
                vocab = self._parse_vocab_json(text)
                logger.info(
                    "LLM vocab extraction for %s (attempt %d): %d predicates, %d constants",
                    problem.id,
                    attempt + 1,
                    len(vocab["predicates"]),
                    len(vocab["constants"]),
                )
                return vocab
            except Exception as e:
                last_error = e
                logger.warning(
                    "LLM vocab extraction attempt %d failed for %s: %s",
                    attempt + 1,
                    problem.id,
                    e,
                )

        logger.error(
            "LLM vocab extraction failed for %s after %d attempts: %s",
            problem.id,
            self._api.max_retries,
            last_error,
        )
        return {"predicates": {}, "constants": {}}

    @staticmethod
    def _parse_vocab_json(text: str) -> dict:
        # Strip markdown code fences if present
        text = re.sub(r"```(?:json)?\s*", "", text).strip()
        text = text.rstrip("`").strip()

        data = json.loads(text)
        vocab: dict = {"predicates": {}, "constants": {}}

        for name, info in data.get("predicates", {}).items():
            vocab["predicates"][name] = {
                "arity": int(info.get("arity", 1)),
                "description": str(info.get("description", "")),
            }
        for name, info in data.get("constants", {}).items():
            vocab["constants"][name] = {
                "sort": str(info.get("sort", "entity")),
                "description": str(info.get("description", name)),
            }
        return vocab

